          html: `<table class="tbl"><tr><th>内分泌腺</th><th>激素</th><th>主要作用</th><th>分泌异常</th></tr>
<tr><td><b>垂体</b></td><td><b>生长激素</b></td><td>调节人体的生长发育</td><td>幼年不足：<b>侏儒症</b>（身材矮小，<b>智力正常</b>）<br>幼年过多：巨人症<br>成年过多：肢端肥大症</td></tr>
<tr><td><b>甲状腺</b></td><td><b>甲状腺激素</b></td><td>促进新陈代谢和生长发育，提高神经系统的兴奋性</td><td>幼年不足：<b>呆小症</b>（身材矮小，<b>智力低下</b>，生殖器官发育不全）<br>成年过多：甲状腺功能亢进（甲亢）<br>缺<b>碘</b>：<b>地方性甲状腺肿</b>（大脖子病）</td></tr>
<tr><td><b>胰岛</b>（散布在胰腺中的细胞群）</td><td><b>胰岛素</b></td><td>调节糖类在体内的吸收、利用和转化，<b>降低血糖</b></td><td>分泌不足：<b>糖尿病</b></td></tr>
<tr><td>肾上腺</td><td>肾上腺素</td><td>使心跳加快、血压升高等</td><td></td></tr>
<tr><td>性腺（睾丸、卵巢）</td><td>雄性激素、雌性激素</td><td>促进生殖器官发育和生殖细胞生成，激发并维持第二性征</td><td></td></tr></table>
<div class="key">① <b>碘</b>是合成甲状腺激素的原料：缺碘地区要吃加碘食盐，多吃海带、紫菜等含碘丰富的食物。<br>② 胰岛素是一种<b>蛋白质</b>，口服会在消化道内被消化分解而失去作用，所以糖尿病患者要<b>注射</b>胰岛素，不能口服。</div>
<p class="warn">侏儒症和呆小症都是“幼年矮小”，区别在<b>智力</b>：侏儒症（生长激素）智力正常，呆小症（甲状腺激素）智力低下。<br>胰腺有两部分：外分泌部分泌胰液（经导管流入小肠），胰岛属于内分泌腺。</p>`
