      prereqs: ['b-virus'],
      tip: '必考“三环节、三措施”：病人、带病原体的动物是传染源，病毒、细菌等是病原体，不要混；隔离治疗病人属于控制传染源，消毒、戴口罩、勤洗手、灭蚊蝇属于切断传播途径，接种疫苗、锻炼身体属于保护易感人群。判断是不是传染病，看它是不是由病原体引起、能不能传播。',
