        {
          h: '预防措施：控制传染源、切断传播途径、保护易感人群',
          html: `<p>既然三个环节缺一不可，那么切断其中任何一个环节，传染病就流行不起来。所以预防措施也分三类：</p>
<table class="tbl"><tr><th>措施类别</th><th>针对的环节</th><th>常见做法</th></tr>
<tr><td><b>控制传染源</b></td><td>传染源</td><td>对病人<b>早发现、早报告、早隔离、早治疗</b>；捕杀或处理患病的动物；给狗接种狂犬病疫苗（针对狗这个可能的传染源）</td></tr>
<tr><td><b>切断传播途径</b></td><td>传播途径</td><td><b>戴口罩</b>、开窗<b>通风</b>、<b>勤洗手</b>、对环境和用具<b>消毒</b>、不喝生水、饭前便后洗手、<b>灭蚊灭蝇</b>、不共用毛巾和牙刷</td></tr>
<tr><td><b>保护易感人群</b></td><td>易感人群</td><td><b>接种疫苗</b>、<b>加强体育锻炼</b>增强体质、流行期间少去人多的地方</td></tr></table>
<div class="key">判断口诀：<b>对“病人/病畜”下手</b>的是控制传染源；<b>对“环境、物品、动作习惯”下手</b>的是切断传播途径；<b>对“还没得病的健康人”下手</b>（打疫苗、锻炼）的是保护易感人群。</div>
<p class="warn">易错：①“对病人的衣物、餐具消毒”——消毒的是物品，属于<b>切断传播途径</b>，不是控制传染源。②“给健康的同学打疫苗”是保护易感人群；“隔离治疗患病同学”是控制传染源。③“戴口罩”是切断传播途径，不管是病人戴还是健康人戴，都是在阻断病原体的传播。</p>`
        }
