      keywords: '生态系统 生物部分 非生物部分 生产者 消费者 分解者 绿色植物 细菌 真菌 蘑菇 腐生 物质循环 碳循环 光合作用 呼吸作用 分解作用 自我调节能力 自动调节 生态平衡 生态瓶',
      prereqs: ['b-bio-env'],
      tip: '常考：判断哪些属于生态系统（必须有生物和非生物部分）；生产者、消费者、分解者的判断和作用（蘑菇是分解者）；识图找生产者——和“大气中的二氧化碳”之间有双向箭头的是生产者；自我调节能力有一定限度，生物种类越多、营养结构越复杂，自我调节能力越强。',
      learn: [
        {
          h: '什么是生态系统',
          html: `<p>在一定的空间范围内，<b>生物</b>与<b>环境</b>所形成的统一的整体，叫作<b>生态系统</b>。一片森林、一块农田、一个池塘、一片草原，都可以看作一个生态系统。</p>
<div class="key">判断是不是生态系统：既要有<b>全部生物</b>（植物、动物、细菌、真菌等），又要有<b>非生物部分</b>（阳光、空气、水、土壤等），二者缺一不可。</div>
<table class="tbl"><tr><th>说法</th><th>是不是生态系统</th></tr>
<tr><td>一片森林、一个池塘</td><td>✔ 是</td></tr>
<tr><td>池塘里所有的鱼</td><td>✘ 只有部分生物</td></tr>
<tr><td>森林里所有的生物</td><td>✘ 缺少非生物部分</td></tr>
<tr><td>草原上的阳光、空气和土壤</td><td>✘ 缺少生物部分</td></tr></table>`
        },
        {
          h: '生态系统的组成：生产者、消费者、分解者',
          html: `${gEcoFig(false)}
<table class="tbl"><tr><th>组成</th><th>主要是</th><th>作用</th></tr>
<tr><td><b>非生物部分</b></td><td>阳光、空气、水、温度、土壤等</td><td>为生物提供能量、营养和生存空间</td></tr>
<tr><td><b>生产者</b></td><td><b>绿色植物</b></td><td>通过<b>光合作用</b>把无机物合成有机物，把光能储存在有机物中；为自身和其他生物提供食物和能量</td></tr>
<tr><td><b>消费者</b></td><td>各种<b>动物</b></td><td>直接或间接以植物为食；能<b>促进物质循环</b>，还能帮助植物传粉、传播种子</td></tr>
<tr><td><b>分解者</b></td><td><b>细菌和真菌</b>（营腐生生活的）</td><td>把动植物遗体、粪便中的有机物分解成<b>二氧化碳、水和无机盐</b>，归还到环境中，再被植物利用</td></tr></table>
<p class="warn">① <b>蘑菇</b>是真菌，靠分解朽木、落叶中的有机物生活，属于<b>分解者</b>，不是生产者。<br>② 不是所有细菌都是分解者：寄生在人体内的病菌就不是。<br>③ 蚯蚓、蜣螂（屎壳郎）等以腐烂的有机物为食的动物，也起分解作用，按课本归类为准。<br>④ 生产者、消费者之间“吃与被吃”形成食物链和食物网，详见“食物链和食物网”知识点。</p>
<div class="key">识图找成分：和非生物部分（大气中的二氧化碳）之间有<b>双向箭头</b>的是<b>生产者</b>；生产者和消费者都有箭头指向的是<b>分解者</b>；剩下的是消费者。</div>`
        },
        {
          h: '物质循环：碳在生物和环境之间往返',
          html: `<p>生态系统中的物质是可以<b>循环</b>的。以碳为例（看图 1 的箭头）：</p>
<div class="steps"><p>大气中的二氧化碳 —（生产者的<b>光合作用</b>）→ 植物体内的有机物</p><p>植物体内的有机物 —（被吃）→ 动物体内的有机物</p><p>动植物的有机物 —（自身的<b>呼吸作用</b>）→ 二氧化碳，回到大气</p><p>动植物遗体、粪便 —（分解者的<b>分解作用</b>）→ 二氧化碳、水和无机盐，回到环境</p></div>
<div class="key">二氧化碳进入生物体靠<b>光合作用</b>；回到大气靠动植物的<b>呼吸作用</b>和分解者的<b>分解作用</b>（还有燃料燃烧）。如果没有分解者，动植物遗体会堆积如山，物质就不能顺利循环。</div>
<p class="warn">物质可以<b>循环</b>利用；能量却是沿食物链<b>单向流动、逐级递减</b>的，不能循环（见“食物链和食物网”）。</p>`
        },
        {
          h: '生态系统的自我调节能力与生态瓶',
          html: `<p>在一般情况下，生态系统中各种生物的<b>数量和所占的比例是相对稳定的</b>（不是一成不变的）。例如草原上兔子多了，草被吃掉得多，狼的食物也多了，兔子又会减少……这是因为生态系统具有一定的<b>自我调节能力</b>（旧版教材叫“自动调节能力”）。</p>
<div class="key">① 生物种类越多、营养结构（食物网）越复杂，自我调节能力<b>越强</b>；种类少、结构简单的，自我调节能力弱。<br>② 自我调节能力是<b>有一定限度</b>的。外界干扰超过了这个限度（如过度放牧、大量捕杀某种动物、严重污染），生态系统就会遭到破坏，很难恢复。</div>
<p><b>生态瓶</b>是一个人工制作的小型生态系统：透明的瓶里放河水、河泥（含有分解者）、水草（生产者）、小鱼或小螺（消费者），密封后放在<b>有散射光</b>的地方。</p>
<table class="tbl"><tr><th>制作要求</th><th>原因</th></tr>
<tr><td>瓶子透明，放在有光的地方</td><td>水草要进行光合作用，制造有机物、释放氧气</td></tr>
<tr><td>避免阳光直射</td><td>防止瓶内温度过高</td></tr>
<tr><td>放入河泥</td><td>河泥中有细菌、真菌等分解者</td></tr>
<tr><td>动物不能放太多</td><td>动物多，消耗的氧气和食物多，会超过生态瓶的自我调节能力</td></tr></table>
<p class="warn">生态瓶里生物种类少、结构简单，自我调节能力很弱，所以维持的时间有限。</p>`
        }
      ],
