<table class="tbl"><tr><th>类型</th><th>主要特点</th></tr>
<tr><td><b>森林生态系统</b></td><td>分布在较湿润的地区，动植物种类繁多，营养结构复杂，自我调节能力较强；能涵养水源、保持水土、调节气候，有“<b>绿色水库</b>”“<b>地球之肺</b>”之称（福建武夷山有大片森林）</td></tr>
<tr><td><b>草原生态系统</b></td><td>分布在比较干旱的地区，缺乏高大植物，动物大多善于挖洞或快速奔跑</td></tr>
<tr><td><b>海洋生态系统</b></td><td>由海洋和海洋生物组成，植物以微小的<b>浮游植物</b>为主，能制造大量氧气</td></tr>
<tr><td><b>淡水生态系统</b></td><td>由河流、湖泊、池塘等淡水水域和其中的生物组成，为人类提供饮用水、灌溉和工业用水</td></tr>
<tr><td><b>湿地生态系统</b></td><td>沼泽、河流湖泊的浅水区、沿海滩涂和红树林等；能净化水质、蓄洪抗旱，被称为“<b>地球之肾</b>”</td></tr>
<tr><td><b>农田生态系统</b></td><td>以农作物为主，动植物种类相对较少；<b>人的作用非常关键</b>，离开人的管理，农作物就会被杂草取代</td></tr>
<tr><td><b>城市生态系统</b></td><td><b>人类起主导作用</b>，植物种类和数量较少，消费者主要是人；需要从其他生态系统输入大量物质和能量，自我调节能力弱</td></tr></table>
