          write: true,
          sample: '<p>森林：湿润地区；动植物种类繁多，自我调节能力较强；“绿色水库”“地球之肺”。<br>草原：干旱地区；缺乏高大植物，动物善于挖洞或奔跑；畜牧业基地。<br>海洋：海洋和海洋生物；植物以浮游植物为主；制造大量氧气。<br>湿地：沼泽、滩涂、红树林等；生物种类多；净化水质、蓄洪抗旱，“地球之肾”。<br>农田：以农作物为主；生物种类少，人的作用关键；提供粮食。<br>城市：人类起主导作用；植物少，消费者主要是人；依赖其他生态系统输入物质和能量。</p><p>各生态系统通过河流、大气流动、水循环和生物迁徙等相互联系，所以生物圈是一个统一的整体，是最大的生态系统。</p>',
